pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 futureTime) public {
        vm.assume(caller != address(0));
        uint256 start = block.timestamp;
        uint256 t = start + (futureTime % 100001);
        vm.warp(t);

        uint256 amount = 10 ether;
        vm.deal(caller, amount);
        uint256 prev = c.pastBlockTime();

        bool ok;
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}("");
        ok = success;

        assertTrue(ok && c.pastBlockTime() > prev);
    }
}
